24	    /** The identityKey of a stored owner, from its telephone, email and householdId. */
25	    public static String of(Owner owner) {
26	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
27	    }
28	
29	    /** The identityKey for the given telephone, email and householdId. */
30	    public static String of(String telephone, String email, String householdId) {
31	        String tel = OwnerTelephone.canonical(telephone);
32	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
33	        String household = (householdId == null) ? "" : householdId;
34	        return tel + "|" + mail + "|" + household;
35	    }
36	}
