8	/**
9	 * Shared SHA-256 hex derivation. Several owner-identity values are the hex encoding of a
10	 * SHA-256 digest — the full lower-case digest (the duplicate-detection identity key), the
11	 * first 12 upper-hex chars (the household id, see
12	 * {@code org.springframework.samples.petclinic.rest.function.owner.OwnerHousehold}) and the
13	 * first 8 upper-hex chars (the customerCode hash, see
14	 * {@code org.springframework.samples.petclinic.rest.function.owner.AssignOwnerCustomerCode}) —
15	 * so the digest itself is computed here once rather than reimplemented per call site.
16	 */
17	public final class Sha256 {
18	
19	    private Sha256() {
20	    }
21	
22	    /** Full lower-case hex of the SHA-256 digest over the UTF-8 bytes of {@code input}. */
23	    public static String hex(String input) {
24	        try {
25	            byte[] digest = MessageDigest.getInstance("SHA-256")
26	                    .digest(input.getBytes(StandardCharsets.UTF_8));
27	            StringBuilder sb = new StringBuilder(digest.length * 2);
28	            for (byte b : digest) {
29	                sb.append(String.format("%02x", b));
30	            }
31	            return sb.toString();
32	        }
33	        catch (NoSuchAlgorithmException e) {
34	            throw new IllegalStateException(e);
35	        }
36	    }
37	
38	    /** The first {@code n} upper-case hex characters of the SHA-256 digest of {@code input}. */
39	    public static String hexPrefix(String input, int n) {
40	        return hex(input).substring(0, n).toUpperCase(Locale.ROOT);
41	    }
42	}
