8	/**
9	 * Rejects a create-owner request that would be a second member of an existing household,
10	 * responding 409. The household is keyed on (lastName, postcode), so its deterministic
11	 * {@code householdId} (see {@link OwnerHousehold}) is shared by every owner with the same last
12	 * name and postcode; if any existing owner already carries that householdId, this request is a
13	 * household duplicate.
14	 *
15	 * <p>The {@code sharesHousehold} request flag bypasses this block: it no longer creates the
16	 * household link (the link is now automatic and deterministic) but declares that the caller
17	 * intends to join the existing household, so the owner is created as a declared household
18	 * member instead of being rejected. Such a declared member is later NOT flagged as a possible
19	 * duplicate (see {@link AssignOwnerPossibleDuplicate}).
20	 *
21	 * <p>Runs after {@link ValidateOwnerFields} and before {@link BuildOwner}; the request's
22	 * householdId is the same value {@link AssignOwnerHousehold} later stamps onto the owner. An
23	 * owner with no postcode has no household and is never a household duplicate.
24	 */
25	public class EnsureUniqueOwnerIdentity {
26	
27	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
28	            throws DuplicateOwnerIdentityException {
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return; // declared household member — bypass the duplicate block
31	        }
32	        String householdId = OwnerHousehold.idFor(request.getLastName(), request.getPostcode());
33	        if (householdId == null) {
34	            return; // no postcode, so no household to collide with
35	        }
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (existing.isDeleted()) {
38	                continue; // a soft-deleted owner no longer blocks a new one
39	            }
40	            if (householdId.equals(existing.getHouseholdId())) {
41	                throw new DuplicateOwnerIdentityException(householdId);
42	            }
43	        }
44	    }
45	}
