10	 * Flags an owner as a soft-match ("possible duplicate") of an existing owner: one that is
11	 * <em>not</em> a hard duplicate (see {@link EnsureUniqueOwnerIdentity}) yet shares another
12	 * owner's {@code lastName} (compared case-insensitively) and {@code postcode} while carrying a
13	 * different telephone (compared in canonical E.164 form, see {@link OwnerTelephone}).
14	 *
15	 * <p>A fellow member of the same household (same deterministic {@code householdId}, see
16	 * {@link OwnerHousehold}) is excluded: sharing a household is a <em>declared</em> relationship
17	 * admitted via the {@code sharesHousehold} flag, not a suspected duplicate. Because the
18	 * householdId is derived from (lastName, postcode), this is exactly the set of owners a soft
19	 * match would otherwise catch, so a declared household member is never flagged.
20	 *
21	 * <p>Such an owner is still created; this step only records the transient {@code possibleDuplicate}
22	 * flag and, when true, the {@code possibleDuplicateOf} id of the matching owner — the earliest
23	 * (lowest id) match when several exist. When nothing matches, {@code possibleDuplicate} is false
24	 * and {@code possibleDuplicateOf} is null.
25	 *
26	 * <p>Runs on both the create pipeline (after Save) and the read pipeline, so the flag is identical
27	 * whether returned from the create response or a later GET, mirroring
28	 * {@link AssignOwnerBulkSignupWarning} and {@link AssignOwnerHouseholdSize}. Both derived values
29	 * are never persisted.
30	 */
31	public class AssignOwnerPossibleDuplicate {
32	
33	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
34	        String lastName = owner.getLastName();
35	        String postcode = owner.getPostcode();
36	        if (postcode == null || postcode.isBlank()) {
37	            owner.setPossibleDuplicate(false);
38	            owner.setPossibleDuplicateOf(null);
39	            return;
40	        }
41	        String telephone = OwnerTelephone.canonical(owner.getTelephone());
42	        String householdId = owner.getHouseholdId();
43	        Owner match = ownerRepository.findAll().stream()
44	                .filter(existing -> existing.getId() != null
45	                        && (owner.getId() == null || !existing.getId().equals(owner.getId())))
46	                .filter(existing -> householdId == null || !householdId.equals(existing.getHouseholdId()))
47	                .filter(existing -> equalsIgnoreCase(existing.getLastName(), lastName)
48	                        && postcode.equals(existing.getPostcode())
49	                        && !telephone.equals(OwnerTelephone.canonical(existing.getTelephone())))
50	                .min(Comparator.comparingInt(Owner::getId))
51	                .orElse(null);
52	        if (match == null) {
53	            owner.setPossibleDuplicate(false);
54	            owner.setPossibleDuplicateOf(null);
55	        }
56	        else {
57	            owner.setPossibleDuplicate(true);
58	            owner.setPossibleDuplicateOf(match.getId());
59	        }
60	    }
61	
62	    private static boolean equalsIgnoreCase(String a, String b) {
63	        return a == null ? b == null : a.equalsIgnoreCase(b);
64	    }
