17	    /** A pragmatic address check: one {@code @}, non-empty local and domain parts, a dotted domain. */
18	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
19	
20	    /** Disposable email domains rejected outright. */
21	    private static final Set<String> BLOCKED_DOMAINS =
22	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
23	
24	    private OwnerEmail() {
25	    }
26	
27	    /**
28	     * If the request carries a non-blank email, validate and lower-case it in place; otherwise leave
29	     * it as-is.
30	     */
31	    static void normalize(OwnerFieldsDto request)
32	            throws InvalidOwnerEmailException, DisposableOwnerEmailException {
33	        String email = request.getEmail();
34	        if (email == null || email.isBlank()) {
35	            return;
36	        }
37	        if (!EMAIL.matcher(email).matches()) {
38	            throw new InvalidOwnerEmailException(email);
39	        }
40	        String normalized = email.toLowerCase();
41	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
42	        if (BLOCKED_DOMAINS.contains(domain)) {
43	            throw new DisposableOwnerEmailException(email);
